    [3, 3, 3, 1, 1, 1, 1, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    [3, 6, 6, 6, 6, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 8, 8, 8, 8, 3, 3, 3],
    [3, 6, 3, 3, 6, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 8, 3, 3, 8, 3, 3, 3],
    [3, 6, 3, 3, 6, 3, 9, 9, 9, 9, 3, 3, 3, 3, 3, 8, 3, 3, 8, 3, 3, 3],
    [3, 6, 6, 6, 6, 3, 9, 3, 3, 9, 3, 3, 3, 3, 3, 8, 8, 8, 8, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 9, 3, 3, 9, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 9, 9, 9, 9, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
]

print(f"Input dimensions: {len(input_grid)} x {len(input_grid[0])}")

# Find all hollow rectangle outlines
shapes = {}
for r in range(len(input_grid)):
    for c in range(len(input_grid[0])):
        color = input_grid[r][c]
        if color != 3 and color not in shapes:
            shapes[color] = []

print(f"\nFound {len(shapes)} different outline colors in input")
for color, positions in shapes.items():
    print(f"  Color {color}: {len(positions)} pixels")

# Based on task-188ed2e8 fill_rule_final:
# "fill each interior FULLY with 2 if interior area is even, 7 if odd"
print("\n\nFill Rule: interior area even -> fill with 2, odd -> fill with 7")

# Calculate expected output
output = [row[:] for row in input_grid]

# Shape 1: Color 6 at r1c3, 3x3 hollow -> interior 1x1 = 1 cell (odd) -> fill with 7
# Rows 1-3, Cols 3-5
for r in range(1, 4):
    for c in range(3, 6):
        if input_grid[r][c] == 3 and 1 <= r <= 3 and 3 <= c <= 5:  # interior
            output[r][c] = 7

# Shape 2: Color 9 at r1c7, 3x3 hollow -> interior 1x1 = 1 cell (odd) -> fill with 7
# Rows 1-3, Cols 7-9
for r in range(1, 4):
    for c in range(7, 10):
        if input_grid[r][c] == 3 and 1 <= r <= 3 and 7 <= c <= 9:
            output[r][c] = 7

# Shape 3: Color 9 at r5c4, 3x3 hollow -> interior 1x1 = 1 cell (odd) -> fill with 7
# Rows 5-7, Cols 4-6
for r in range(5, 8):
    for c in range(4, 7):
        if input_grid[r][c] == 3 and 5 <= r <= 7 and 4 <= c <= 6:
            output[r][c] = 7

# Shape 4: Color 4 at r7c14, 4x2 hollow -> interior 2x1 = 2 cells (even) -> fill with 2
# Rows 7-10, Cols 14-17
for r in range(7, 11):
    for c in range(14, 18):
        if input_grid[r][c] == 3 and 7 <= r <= 10 and 14 <= c <= 17:
            output[r][c] = 2

# Shape 5: Color 6 at r8c8, 4x2 hollow -> interior 2x1 = 2 cells (even) -> fill with 2
# Rows 8-11, Cols 8-12
for r in range(8, 12):
    for c in range(8, 13):
        if input_grid[r][c] == 3 and 8 <= r <= 11 and 8 <= c <= 12:
            output[r][c] = 2

# Shape 6: Color 1 at r10c3, 3x3 hollow -> interior 1x1 = 1 cell (odd) -> fill with 7
# Rows 10-12, Cols 3-6
for r in range(10, 13):
    for c in range(3, 7):
        if input_grid[r][c] == 3 and 10 <= r <= 12 and 3 <= c <= 6:
            output[r][c] = 7

# Shape 7: Color 6 at r15c1, 3x3 hollow -> interior 1x1 = 1 cell (odd) -> fill with 7
# Rows 15-17, Cols 1-4
for r in range(15, 18):
    for c in range(1, 5):
        if input_grid[r][c] == 3 and 15 <= r <= 17 and 1 <= c <= 4:
            output[r][c] = 7

# Shape 8: Color 8 at r15c15, 3x3 hollow -> interior 1x1 = 1 cell (odd) -> fill with 7
# Rows 15-17, Cols 15-18
for r in range(15, 18):
    for c in range(15, 19):
        if input_grid[r][c] == 3 and 15 <= r <= 17 and 15 <= c <= 18:
            output[r][c] = 7

# Shape 9: Color 9 at r17c6, 3x3 hollow -> interior 1x1 = 1 cell (odd) -> fill with 7
# Rows 17-19, Cols 6-9
for r in range(17, 20):
    for c in range(6, 10):
        if input_grid[r][c] == 3 and 17 <= r <= 19 and 6 <= c <= 9:
            output[r][c] = 7

# Verify special areas left empty
print("\n\nChecking for shapes left empty (should be empty rows):")
print("Shape 4 at r8c8: area=2 (even), should fill with 2")
print("Shape 5 at r10c3: area=2 (even), should fill with 2")
print("Shape 7 at r15c1: area=3 (odd), should fill with 7")

print("\n\nOutput preview (first 15 rows):")
for i, row in enumerate(output[:15]):
    print(f"Row {i}: {' '.join(map(str, row))}")

print("\n\nOutput preview (rows 15-22):")
for i, row in enumerate(output[15:]):
    print(f"Row {15+i}: {' '.join(map(str, row))}")

